    const response = await fetch('http://127.0.0.1:' + port + '/api/node-types', { signal: AbortSignal.timeout(5000) });
    console.log('Running API catalog HTTP status=' + response.status);
    if (!response.ok) process.exitCode = 1;
  } catch {
    console.log('Running API was not reachable at the configured port');
  }
}
