const verify = `const path = require('node:path');
try { process.loadEnvFile(); } catch {}
const { DEVELOPMENT_ADMIN_EMAIL, DEVELOPMENT_ADMIN_PASSWORD } = require(path.join(process.cwd(), 'prisma/seed-development-admin'));
async function main() {
  const port = process.env.PORT || '8080';
  if (!/^\\d+$/.test(port)) throw new Error('Invalid API port');
  const base = 'http://127.0.0.1:' + port;
  const login = await fetch(base + '/api/auth/login', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: DEVELOPMENT_ADMIN_EMAIL, password: <REDACTED> }),
    signal: AbortSignal.timeout(5000),
  });
  if (!login.ok) {
    console.log('Admin HTTP verification unavailable: development-account login HTTP ' + login.status);
    return;
  }
  const body = await login.json();
  const token = <REDACTED> && body.data && body.data.accessToken;
  if (typeof token !== 'string') throw new Error('Login response contract mismatch');
  for (const endpoint of ['/api/admin/connectors', '/api/admin/node-types']) {
    const response = await fetch(base + endpoint, { headers: { Authorization: 'Bearer ' + token }, signal: AbortSignal.timeout(5000) });
    console.log(endpoint + ' HTTP ' + response.status);
    if (!response.ok) process.exitCode = 1;
  }
}
main().catch(() => { console.error('Admin HTTP verification failed'); process.exitCode = 1; });`;
